/* Video: this machine's framebuffer, plus the dummy so a program that asks
 * for no display still starts. `SDL_VIDEODRIVER=glados` or nothing at all,
 * since the list below is tried in order. */
#define SDL_VIDEO_DRIVER_GLADOS 1
#define SDL_VIDEO_DRIVER_DUMMY 1
#define SDL_VIDEO_RENDER_SW 1

/* `linux/input.h`, which zig ships kernel headers for. It gates more than it
 * looks: `SDL_evdev_capabilities.h` puts the device-class constants *and* the
 * NBITS/test_bit macros behind it, so without this the evdev reader compiles
 * to a wall of undeclared identifiers that read like a missing library. */
#define HAVE_LINUX_INPUT_H 1

/* evdev, which is SDL's own unmodified reader of the devices this kernel
 * grew for exactly this. */
#define SDL_INPUT_LINUXEV 1

#define SDL_AUDIO_DRIVER_DUMMY 1
#define SDL_JOYSTICK_DUMMY 1
#define SDL_HAPTIC_DUMMY 1
